n budget is too low for rich meal selection.","resolution":"CODE_CHANGE"}],"dj":[{"requirement":"I/O contract","change":"Added deterministic planner function returning structured days and shoppingList arrays, and wired UI rendering to those outputs.","files":["src/planner.js","src/App.jsx"]},{"requirement":"Success criteria","change":"Implemented meal selection with uniqueness checks, a 7-meal target, and budget-aware fallback meals so total planned cost remains within budget.","files":["src/planner.js"]},{"requirement":"Objective","change":"Added fixed 7-day dinner plan generation and README guidance describing the weekly planner contract.","files":["src/planner.js","README.md"]}]},"framework":"React + Vite","language":"javascript","files":[{"path":"package.json","language":"javascript","content":"{
