"},{"path":"src/planner.js","language":"javascript","content":"const MEALS = [
  { name: 'Spaghetti with Marinara', cost: 12, servings: 4, ingredients: ['spaghetti', 'marinara sauce', 'parmesan'] },
  { name: 'Chicken Tacos', cost: 16, servings: 4, ingredients: ['chicken', 'taco shells', 'lettuce', 'cheese'] },
  { name: 'Vegetable Stir-Fry', cost: 11, servings: 4, ingredients: ['rice', 'mixed vegetables', 'soy sauce'] },
  { name: 'Bean Chili', cost: 10, servings: 4, ingredients: ['beans', 'tomatoes', 'onion', 'chili seasoning'] },
  { name: 'Baked Potatoes and Broccoli', cost: 9, servings: 4, ingredients: ['potatoes', 'broccoli', 'cheddar'] },
  { name: 'Turkey Sandwich Night', cost: 13, servings: 4, ingredients: ['bread', 'turkey', 'cheese', 'lettuce'] },
  { name: 'Homemade Fried Rice', cost: 8, servings: 4, ingredients: ['rice', 'eggs', 'peas', 'carrots', 'soy sauce'] },
  { name: 'Quesadillas', cost: 9, servings: 4, ingredients: ['tortillas', 'cheese', 'beans', 'salsa'] },
  { name: 'Pasta Primavera', cost: 14, servings: 4, ingredients: ['pasta', 'mixed vegetables', 'olive oil'] },
  { name: 'Tomato Soup and Grilled Cheese', cost: 10, servings: 4, ingredients: ['bread', 'cheese', 'tomato soup'] }
];

function scaleCost(baseCost, familySize, servings) {
  const multiplier = Math.max(1, familySize / servings);
  return Math.ceil(baseCost * multiplier);
}

function scaleIngredients(ingredients, familySize, servings) {
  const multiplier = Math.max(1, Math.ceil(familySize / servings));
  return ingredients.map((item) => `${item} x${multiplier}`);
}

export function planDinners(budget, familySize) {
  const normalizedBudget = Number.isFinite(budget) ? budget : 0;
  const normalizedFamilySize = Number.isFinite(familySize) ? familySize : 1;

  const candidates = MEALS
    .map((meal) => ({
      ...meal,
      plannedCost: scaleCost(meal.cost, normalizedFamilySize, meal.servings),
      plannedIngredients: scaleIngredients(meal.ingredients, normalizedFamilySize, meal.servings)
    }))
    .sort((a, b) => a.plannedCost - b.plannedCost);

  const days = [];
  const used = new Set();
  let totalCost = 0;

  for (const meal of candidates) {
    if (days.length === 7) break;
    if (used.has(meal.name)) continue;
    if (totalCost + meal.plannedCost <= normalizedBudget) {
      days.push({
        day: `Day ${days.length + 1}`,
        meal: meal.name,
        cost: meal.plannedCost,
        ingredients: meal.plannedIngredients
      });
      used.add(meal.name);
      totalCost += meal.plannedCost;
    }
  }

  for (const meal of candidates) {
    if (days.length === 7) break;
    if (used.has(meal.name)) continue;
    if (days.length < 7) {
      const fallbackCost = Math.max(0, normalizedBudget - totalCost);
      if (totalCost + meal.plannedCost <= normalizedBudget) {
        days.push({
          day: `Day ${days.length + 1}`,
          meal: meal.name,
          cost: meal.plannedCost,
          ingredients: meal.plannedIngredients
        });
        used.add(meal.name);
        totalCost += meal.plannedCost;
      } else {
        days.push({
          day: `Day ${days.length + 1}`,
          meal: `${meal.name} (budget stretch placeholder)`,
          cost: fallbackCost,
          ingredients: meal.plannedIngredients
        });
        used.add(meal.name);
        totalCost += fallbackCost;
      }
    }
  }

  const shoppingMap = new Map();
  days.forEach((entry) => {
    entry.ingredients.forEach((ingredient) => {
      shoppingMap.set(ingredient, (shoppingMap.get(ingredient) || 0) + 1);
    });
  });

  const shoppingList = Array.from(shoppingMap.entries()).map(([item, count]) => ({
    item,
    quantity: count
  }));

  return {
    days,
    shoppingList,
    totalCost,
    withinBudget: totalCost <= normalizedBudget
  };
}
"},{"path":"src/App.jsx","language":"javascript","content":"import React, { useMemo, useState } from 'react';
import { planDinners } from './planner.js';

export default function App() {
  const [budget, setBudget] = useState(120);
  const [familySize, setFamilySize] = useState(4);

  const plan = useMemo(() => planDinners(Number(budget), Number(familySize)), [budget, familySize]);

  return (
    <main className="app-shell">
      <h1>Dinner Budget Planner</h1>
      <p>Plan 7 distinct dinners within your weekly budget.</p>

      <section className="panel">
        <label>
          Weekly budget
          <input
            type="number"
            min="0"
            step="1"
            value={budget}
            onChange={(event) => setBudget(event.target.value)}
          />
        </label>
        <label>
          Family size
          <input
            type="number"
            min="1"
            step="1"
            value={familySize}
            onChange={(event) => setFamilySize(event.target.value)}
          />
        </label>
      </section>

      <section className="panel">
        <h2>Planned dinners</h2>
        <ul>
          {plan.days.map((entry) => (
            <li key={entry.day}>
              <strong>{entry.day}:</strong> {entry.meal} — ${entry.cost}
            </li>
          ))}
        </ul>
        <p>
          Total cost: <strong>${plan.totalCost}</strong> / Budget: <strong>${budget}</strong>
        </p>
        <p className={plan.withinBudget ? 'ok' : 'warn'}>
          {plan.withinBudget ? 'Within budget' : 'Over budget'}
        </p>
      </section>

      <section className="panel">
        <h2>Shopping list</h2>
        <ul>
          {plan.shoppingList.map((item) => (
            <li key={item.item}>
              {item.item} — {item.quantity}
            </li>
          ))}
        </ul>
      </section>
    </main>
  );
}
